1	// The scheduling CALENDAR — the frequency vocabulary and the anchor arithmetic
2	// (docs/PRINCIPLES.md). Pure and stateless: given the repo's `schedule`
3	// anchor (dailyHour, weeklyDay, monthlyDay), a frequency and a `now`, it answers
4	// exactly one question — WHEN is that frequency's most recent occurrence at or
5	// before `now`.
6	//
7	// There is no occurrence IDENTITY here, and that is the point: under the
8	// work-item queue an occurrence is identified by the item's issue number, so the
9	// calendar owns the instants and nothing else. `queue/anchors.mjs` is the only
10	// consumer of the arithmetic; the vocabulary below is what the task contract and
11	// the author-time declaration check read.
12	//
13	// All times are UTC (the `schedule` values are UTC by contract). This module
14	// never reads the clock itself — `now` is always injected — so every answer is
15	// deterministic and testable.
16	
17	// The legal frequency tokens — the vocabulary the runtime contract validates
18	// against and the author-time declaration check rejects anything outside.
19	//
20	// `manual` is the one non-cadence: a manual task has no occurrence at all, so the
21	// scheduler run never instantiates it and it runs only from an item created by hand
22	// (`public/create-work-item.mjs`). It exists for operator levers — work that
23	// answers no recurring question but wants a task's whole apparatus (declaration,
24	// contract validation, code-work, the work item) when a human pulls it.
25	export const FREQUENCIES = ['daily', 'weekly', 'monthly', 'manual'];
26	
27	// The retired spellings, and what each reads as. `hourly` cannot mean anything under a cron that
28	// fires twice a day (PRINCIPLES.md), and the `daily±Nh` offsets staggered dependent tasks by clock
29	// hour where `after:` (PRINCIPLES.md) declares the same intent and actually enforces it.
30	//
31	// This map is PERMANENT, not a migration window. A task declaration is member-owned data that no
32	// vendoring pass rewrites, so a member can carry a retired token indefinitely and must keep
33	// working; `task-declaration-shape` is what stops a NEW declaration naming one.
34	// EMPTIED, NOT DELETED (#1234). The map IS the tolerance, so emptying it collapses
35	// `ACCEPTED_FREQUENCIES` onto `FREQUENCIES`, makes a declaration still naming a retired
36	// token fail contract validation, and leaves `normalizeFrequency` as the identity every
37	// caller can keep calling — nothing is unwired, and the next retirement fills it in again.
38	// Emptied once the fleet's own declarations were read and none named a retired token:
39	// GoogleCalendarEventCreator's `create-extractor` was the last, and moved to `daily`.
40	// @legacy-tolerance advisory:none retire:#1642
41	export const LEGACY_FREQUENCIES = Object.freeze({});
42	
43	// What a declaration may CARRY, as against what a new one may be WRITTEN with.
44	export const ACCEPTED_FREQUENCIES = [...FREQUENCIES, ...Object.keys(LEGACY_FREQUENCIES)];
45	
46	// THE ONE DOOR (PRINCIPLES.md). Applied by `normalizeTaskDeclaration`, so every reader downstream
47	// of a loaded declaration sees a canonical token — and there is more downstream than the
48	// calendar: `periodMs` feeds the janitor's stale-ready bound (`queue/janitor-rules.mjs`) and the
49	// precondition's signal window (`queue/signals.mjs`). Normalizing only the anchor would leave a
50	// task that now runs daily judged stale after two HOURS, which is a spurious needs-human park on
51	// exactly the members this tolerance exists for.
52	export const normalizeFrequency = (frequency) => LEGACY_FREQUENCIES[frequency] ?? frequency;
53	
54	// The documented anchor defaults (docs/PRINCIPLES.md) — applied
55	// when a repo omits `schedule` or any of its keys. This is the single source of
56	// these values; the checks layer's load-time range validation
57	// (engine/checks/helpers/repo-context.mjs) only bounds them, it does not
58	// re-declare them.
59	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
60	
61	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
62	// vocabulary the config validator mirrors.
63	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
64	
65	const HOUR_MS = 3600 * 1000;
66	const DAY_MS = 24 * HOUR_MS;
67	
68	// Last calendar day of a UTC month (day 0 of the next month rolls back).
69	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
70	
71	// Fill any absent key with its documented default; leave present values
72	// untouched (the checks layer has already range-validated them at load).
73	export function normalizeSchedule(schedule = {}) {
74	  const s = schedule || {};
75	  return {
76	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
77	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
78	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
79	  };
80	}
81	
82	// The most recent occurrence of `frequency` at or before `now`, as a Date —
83	// `null` for `manual`, which has none. `now` may be a Date or anything the Date
84	// constructor accepts; `schedule` is normalized here, so callers need not.
85	export function anchorInstant(frequency, schedule, now) {
86	  const s = normalizeSchedule(schedule);
87	  const at = new Date(now);
88	  const nowMs = at.getTime();
89	  // Total over the accepted vocabulary, not just the canonical one: the door normalizes every
90	  // LOADED declaration, and normalizing here too means a direct caller — a test, `slots.mjs`, a
91	  // frequency read off something other than a discovered task — cannot get a different answer.
92	  const freq = normalizeFrequency(frequency);
93	
94	  if (freq === 'manual') return null;
95	
96	  if (freq === 'daily') {
97	    // Walk anchor DATES back from today until the instant is ≤ now: today's anchor hour may not
98	    // have come yet, in which case the most recent occurrence is yesterday's.
99	    let anchor = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
100	    for (;;) {
101	      const time = new Date(anchor.getTime() + s.dailyHour * HOUR_MS);
102	      if (time.getTime() <= nowMs) return time;
103	      anchor = new Date(anchor.getTime() - DAY_MS);
104	    }
105	  }
106	
107	  if (freq === 'weekly') {
108	    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
109	    let date = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
110	    // Up to 8 steps guarantees the previous week's occurrence even when today is
111	    // the weekly day but earlier than dailyHour.
112	    for (let i = 0; i < 8; i += 1) {
113	      if (date.getUTCDay() === targetDow) {
114	        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
115	        if (time.getTime() <= nowMs) return time;
116	      }
117	      date = new Date(date.getTime() - DAY_MS);
118	    }
119	    // Unreachable in practice (a matching weekday always exists within 7 days).
120	    throw new Error(`no weekly occurrence resolved for ${s.weeklyDay}`);
121	  }
122	
123	  if (freq === 'monthly') {
124	    let year = at.getUTCFullYear();
125	    let month = at.getUTCMonth();
126	    for (;;) {
127	      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (docs/PRINCIPLES.md)
128	      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
129	      if (time.getTime() <= nowMs) return time;
130	      month -= 1;
131	      if (month < 0) { month = 11; year -= 1; }
132	    }
133	  }
134	
135	  throw new Error(`unknown frequency "${frequency}"`);
136	}
137	
138	// --- the cadence terms ----------------------------------------------------------
139	// How a task states WHEN it runs, inside its own `preconditions`
140	// (docs/PRINCIPLES.md): the engine keeps no calendar of its own, so the cadence is one of the
141	// task's conditions, read off its own run history at every scheduler tick.
142	//
143	//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
144	//                                this repo's schedule — fixed hours, no drift
145	//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
146	//
147	// Whether a task is asked at all is its `trigger`, not the shape of this list: a
148	// task nothing asks may still state conditions, which are judged when somebody
149	// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
150	//
151	// The parse lives here, beside the frequency vocabulary it replaces, and imports
152	// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
153	export const CADENCES = ['daily', 'weekly', 'monthly'];
154	export const DUE_TERM = 'due';
155	export const ELAPSED_TERM = 'last-run-over';
156	export const NOT_FAILED_TERM = 'last-run-not-failed';
157	export const NOT_PARKED_TERM = 'last-run-not-parked';
158	
159	// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
160	const DURATION_RE = /^(\d+)(h|d)$/;
161	export function parseDuration(text) {
162	  const m = DURATION_RE.exec(String(text ?? ''));
163	  if (!m) return null;
164	  const n = Number(m[1]);
165	  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
166	}
167	
168	// The term references an expression carries: each entry split on `||`, each
169	// reference `{ name, arg }` with the argument after the first colon. The same
170	// grammar precondition-policy.mjs parses, re-spelled here so this module stays
171	// import-free; the policy engine's parse is the one that validates.
172	const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
173	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
174	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
175	
176	// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
177	// 'elapsed', ms, text }`, or null for a task with no cadence term (asked at every
178	// tick while it states any condition, it runs whenever those hold). The first
179	// cadence term wins.
180	export function cadenceOf(preconditions) {
181	  for (const ref of entriesOf(preconditions).flat()) {
182	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
183	    if (ref.name === ELAPSED_TERM) {
184	      const ms = parseDuration(ref.arg);
185	      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
186	    }
187	  }
188	  return null;
189	}
190	
191	// Whether the declaration states any condition at all. Not a scheduling answer on
192	// its own — `trigger` is that — but what the contract's door reads to derive one
193	// for a declaration written before the field existed (#1789). An entry carrying
194	// only separators states nothing, which is why this is not a length test.
195	export const statesConditions = (preconditions) => entriesOf(preconditions).some((alts) => alts.length > 0);
196	
197	// A term gates when it is a whole conjunct of the expression — `['x', …]` gates,
198	// `['due:daily || x']` merely widens.
199	const gatesOn = (preconditions, term) =>
200	  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === term && alts[0].arg === null);
201	
202	// A task stops past its own failure park only when it says so: nothing holds a
203	// task's lane but its own word — `last-run-not-failed` for that park alone, or
204	// `last-run-not-parked`, which holds behind all four and so answers this too.
205	export const holdsOnFailure = (preconditions) =>
206	  gatesOn(preconditions, NOT_FAILED_TERM) || gatesOn(preconditions, NOT_PARKED_TERM);
207	
208	// Whether the declaration holds its lane behind EVERY park, the three a person's
209	// inbox owns included. A reader showing what happens next needs the wider answer
210	// as well: a task held behind an approval park is not being asked on schedule,
211	// and an anchor shown there promises a run the task declines.
212	export const holdsOnAnyPark = (preconditions) => gatesOn(preconditions, NOT_PARKED_TERM);
213	
214	// What the retired `frequency` field always meant, as the term that now says it —
215	// or null for `manual`, which meant no schedule at all and so adds no term.
216	export const cadenceTermFor = (frequency) =>
217	  (normalizeFrequency(frequency) === 'manual' ? null : `${DUE_TERM}:${normalizeFrequency(frequency)}`);
218

