225	      // refresh must not turn its CI red over a declaration nobody has edited yet;
226	      // this only keeps the dead field visible until it is dropped.
227	      if (str('session_scope') !== null) {
228	        advise('declares "session_scope", which nothing reads',
229	          'drop it — reach is a property of which endpoint the hand-off calls, so a task needing wider access declares "invocation_endpoint": <a key in the repo\'s taskScheduler.agenticTaskInvocationEndpoints> instead');
