232	      if (model !== 'none' && !hasNum('agent_execution_timeout')) {
233	        flag('an agentic task (agent_model !== "none") declares no numeric "agent_execution_timeout"', 'add "agent_execution_timeout": seconds bounding the agentic run');
234	      }
235	      if (model === 'none' && !hasCodeWork) {
236	        flag('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
237	      }
238	      if (hasCodeWork) {
239	        const prep = LEGACY_CODE_WORK.reduce((found, { field }) => found ?? str(field), str('code_work'));
240	        if (prep && (/(^|\s)\//.test(prep) || prep.includes('..'))) {
241	          flag('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
242	        }
243	        if (!hasNum('code_work_timeout', ...LEGACY_CODE_WORK.map(({ timeout }) => timeout))) {
244	          flag('"code_work" is set but declares no numeric "code_work_timeout"', 'add "code_work_timeout": seconds after which the subprocess is killed');
245	        }
246	      }
247	    }
248	    return out;
249	  },
250	};
